            <fieldset id="hpp-step-4" x-cloak x-show="step === 4" :disabled="busy || step !== 4" class="bg-white border border-line rounded-2xl p-5"><legend class="sr-only">Overhead produksi</legend><h2 class="text-xl font-bold">Biaya Overhead</h2><p class="text-sm text-gray-600 mt-2">Pilih nominal tetap atau persentase dari biaya bahan + tenaga kerja. Hindari menghitung komponen yang sama dua kali.</p><label for="overhead-mode" class="block text-sm mt-5 mb-2">Metode overhead</label><select id="overhead-mode" x-model="form.overhead_mode" @change="invalidate()" class="w-full"><option value="fixed">Nominal per siklus</option><option value="percentage">Persentase bahan + tenaga kerja</option></select><div x-show="form.overhead_mode === 'fixed'" class="mt-4"><label for="overhead-cost" class="block text-sm mb-2">Overhead per siklus (Rp)</label><input id="overhead-cost" x-model="form.overhead_cost" type="number" min="0" max="99999999.99" step="0.01" :required="form.overhead_mode === 'fixed'" class="w-full"></div><div x-show="form.overhead_mode === 'percentage'" class="mt-4"><label for="overhead-percent" class="block text-sm mb-2">Persentase overhead (0–100%)</label><input id="overhead-percent" x-model="form.overhead_percent" type="number" min="0" max="100" step="0.01" :required="form.overhead_mode === 'percentage'" class="w-full"><label for="overhead-slider" class="sr-only">Geser persentase overhead</label><input id="overhead-slider" x-model="form.overhead_percent" type="range" min="0" max="100" step="0.01" class="w-full mt-4 accent-primary"></div></fieldset>
            <fieldset id="hpp-step-5" x-cloak x-show="step === 5" :disabled="busy || step !== 5" class="bg-white border border-line rounded-2xl p-5"><legend class="sr-only">Hasil dan margin</legend><h2 class="text-xl font-bold">Hasil &amp; Margin</h2><div class="grid sm:grid-cols-2 gap-4 mt-5"><div><label for="pricing-method" class="block text-sm mb-2">Metode rekomendasi harga</label><select id="pricing-method" x-model="form.pricing_method" @change="invalidate()" class="w-full"><option value="margin">Margin (laba ÷ harga jual)</option><option value="markup">Markup (laba ÷ HPP)</option></select></div><div x-show="form.pricing_method === 'margin'"><label for="target-margin" class="block text-sm mb-2">Target margin (%) — opsional</label><input id="target-margin" x-model="form.target_margin" type="number" min="0" max="99.99" step="0.01" class="w-full"></div><div x-show="form.pricing_method === 'markup'"><label for="target-markup" class="block text-sm mb-2">Target markup (%) — opsional</label><input id="target-markup" x-model="form.target_markup" type="number" min="0" max="1000" step="0.01" class="w-full"></div></div><p class="text-xs text-gray-600 mt-3">Margin: HPP ÷ (1 − target%). Markup: HPP × (1 + target%). Target kosong memakai simulasi harga jual untuk tahap pajak.</p><button type="button" @click="calculate()" class="hpp-button hpp-primary mt-4">Hitung Ulang HPP</button>
                <template x-if="result"><div class="mt-5"><div class="hpp-primary rounded-xl p-5"><p>Total HPP satu siklus</p><p class="text-3xl font-bold mt-2" x-text="result.total_hpp === null ? 'Belum lengkap' : money(result.total_hpp)"></p><p class="mt-2" x-text="result.hpp === null ? '' : money(result.hpp) + ' / ' + form.production_unit"></p></div><p x-show="!result.is_complete" class="p-3 bg-amber-50 text-amber-900 mt-3 rounded-xl" x-text="'Lengkapi harga modal: ' + result.missing_costs.join(', ')"></p><dl class="mt-4 space-y-3 text-sm"><div class="flex justify-between gap-3"><dt>Bahan &amp; kemasan / siklus</dt><dd x-text="money(result.ingredients_cost)"></dd></div><div class="flex justify-between gap-3"><dt>Tenaga kerja / siklus</dt><dd x-text="money(result.labor_cost)"></dd></div><div class="flex justify-between gap-3"><dt>Overhead / siklus</dt><dd x-text="money(result.overhead_cost)"></dd></div><div class="flex justify-between gap-3 border-t pt-3"><dt>Laba kotor pada simulasi / unit</dt><dd x-text="result.gross_profit === null ? '—' : money(result.gross_profit)"></dd></div><div class="flex justify-between gap-3"><dt>Margin / markup simulasi</dt><dd x-text="percent(result.margin_percent) + ' / ' + percent(result.markup_percent)"></dd></div><div class="flex justify-between gap-3 font-bold"><dt>Harga acuan rekomendasi / unit</dt><dd x-text="result.suggested_price === null ? '—' : money(result.suggested_price)"></dd></div></dl><p x-show="result.gross_profit < 0" class="text-red-800 text-sm mt-4">Harga simulasi masih di bawah HPP.</p><div class="overflow-x-auto mt-5"><table class="w-full text-sm text-left"><thead><tr class="border-b"><th class="py-2 pr-3" scope="col">Bahan</th><th class="py-2 pr-3" scope="col">Takaran / siklus</th><th class="py-2" scope="col">Biaya</th></tr></thead><tbody><template x-for="line in result.lines" :key="line.raw_material_id"><tr class="border-b"><td class="py-3 pr-3"><span x-text="line.name"></span><small class="block whitespace-pre-wrap break-words" x-text="line.notes"></small></td><td class="py-3 pr-3" x-text="line.amount + ' ' + line.unit"></td><td class="py-3 whitespace-nowrap" x-text="money(line.cost)"></td></tr></template></tbody></table></div></div></template>
            </fieldset>
            <fieldset id="hpp-step-6" x-cloak x-show="step === 6" :disabled="busy || step !== 6" class="bg-white border border-line rounded-2xl p-5"><legend class="sr-only">Simulasi pajak dan harga akhir</legend><h2 class="text-xl font-bold">Pajak &amp; Harga Final</h2><p class="text-sm text-gray-600 mt-2">Simulasi memakai rekomendasi harga, atau harga jual simulasi jika target kosong. Tarif diisi sesuai kebutuhan cafe; ini tidak mengaktifkan pajak di kasir. Pada mode sudah termasuk pajak, pajak dipisahkan dari harga acuan sehingga laba bersih pajak dapat lebih rendah dari target.</p><div class="grid sm:grid-cols-2 gap-4 mt-5"><div><label for="tax-mode" class="block text-sm mb-2">Perlakuan pajak penjualan</label><select id="tax-mode" x-model="form.tax_mode" @change="invalidate()" class="w-full"><option value="exclusive">Ditambahkan ke harga</option><option value="inclusive">Sudah termasuk dalam harga</option></select></div><div><label for="tax-rate" class="block text-sm mb-2">Tarif simulasi (%) — 0 untuk tanpa pajak</label><input id="tax-rate" x-model="form.tax_rate" type="number" min="0" max="100" step="0.01" required class="w-full"></div></div><button type="button" @click="calculate()" class="hpp-button border border-gold-400 text-primary mt-4">Perbarui Harga Final</button><template x-if="result && result.is_complete"><div class="hpp-primary rounded-xl p-5 mt-5"><h3 class="font-bold">Harga Final per Unit</h3><p class="text-3xl font-bold mt-3" x-text="money(result.final_price)"></p><dl class="space-y-3 text-sm mt-4"><div class="flex justify-between gap-3"><dt>Dasar sebelum pajak / unit</dt><dd x-text="money(result.price_before_tax)"></dd></div><div class="flex justify-between gap-3"><dt>Pajak / unit</dt><dd x-text="money(result.tax_amount)"></dd></div><div class="flex justify-between gap-3 border-t border-gold-400 pt-3"><dt>Total untuk semua output</dt><dd x-text="money(result.total_final_price)"></dd></div><div class="flex justify-between gap-3"><dt>Laba setelah pajak penjualan / unit</dt><dd x-text="money(result.profit_after_tax)"></dd></div><div class="flex justify-between gap-3"><dt>Margin setelah pajak penjualan</dt><dd x-text="percent(result.margin_after_tax)"></dd></div></dl></div></template><p class="text-xs text-gray-600 mt-4">Pajak penghasilan usaha tidak otomatis dibebankan ke customer melalui simulasi pajak penjualan ini. Diskon dan biaya platform belum dihitung.</p>@if($product)<button type="button" @click="save()" :disabled="busy || !result || !result.is_complete" class="hpp-button hpp-primary w-full mt-5">Simpan HPP &amp; Resep ke Produk</button><p class="text-xs text-gray-600 mt-2">Menyimpan HPP per unit, resep per unit, dan pengaturan simulasi. Harga jual, stok fisik, dan transaksi lama tetap.</p>@else<p class="text-sm text-primary mt-5">Untuk menyimpan HPP, pilih dan muat produk pada bagian atas halaman.</p>@endif</fieldset>
            <footer class="sticky bottom-0 bg-ivory border-t border-[#d1d5db] p-3 mt-6 flex justify-between gap-3"><button type="button" @click="goTo(step - 1)" :disabled="busy || step === 1" class="hpp-button border border-gold-400">Kembali</button><button type="submit" :disabled="busy || step === 6" class="hpp-button hpp-primary" x-text="busy ? 'Memproses…' : 'Lanjut'">Lanjut</button></footer>
        </form>
    </main>
    <script>
    function hppCalculator() {
        const initial = {{ Illuminate\Support\Js::from($initial) }};
        return {
            form: initial, materials: {{ Illuminate\Support\Js::from($materials) }}, step: 1, furthest: 1,
            steps: ['Produksi', 'Bahan Baku', 'Tenaga Kerja', 'Overhead', 'Hasil & Margin', 'Pajak & Final'],
            outputUnits: ['porsi', 'pcs', 'gram', 'kg', 'ml', 'liter', 'botol', 'pack', 'dus'], materialUnits: {{ Illuminate\Support\Js::from(array_keys(config('inventory.units'))) }},
            result: null, busy: false, error: '', saved: '', nextKey: initial.recipes.length, materialSearch: '',
            newMaterial: {name: '', purchase_total: '', purchase_quantity: '', unit: 'ml'},
            init() { this.form.recipes.forEach((row, index) => row.key = index); },
            invalidate() { this.result = null; this.saved = ''; },
            materialFor(row) { return this.materials.find(material => Number(material.id) === Number(row.raw_material_id)); },
            filteredMaterials(row) { return this.materials.filter(material => Number(material.id) === Number(row.raw_material_id) || material.name.toLocaleLowerCase('id').includes(this.materialSearch.toLocaleLowerCase('id'))); },
            recipeUnits(row) { const unit = (this.materialFor(row)?.unit || '').toLowerCase(); return ['g','gram','kg'].includes(unit) ? ['gram','kg'] : ['ml','l','liter'].includes(unit) ? ['ml','liter'] : unit ? [unit] : []; },
            get purchaseUnitCost() { const total = Number(this.newMaterial.purchase_total), quantity = Number(this.newMaterial.purchase_quantity); return total > 0 && quantity > 0 ? total / quantity : null; },
            money(value) { return new Intl.NumberFormat('id-ID', {style: 'currency', currency: 'IDR', minimumFractionDigits: 2}).format(value); },
            unitMoney(value) { return new Intl.NumberFormat('id-ID', {style: 'currency', currency: 'IDR', minimumFractionDigits: 2, maximumFractionDigits: 6}).format(value); },
            percent(value) { return value === null ? '—' : new Intl.NumberFormat('id-ID', {maximumFractionDigits: 2}).format(value) + '%'; },
            addRow() { this.form.recipes.push({key: this.nextKey++, raw_material_id: '', amount: 1, unit: '', notes: ''}); this.invalidate(); },
            removeRow(index) { this.form.recipes.splice(index, 1); this.invalidate(); },
            validateStep() { const inputs = document.getElementById('hpp-step-' + this.step).querySelectorAll('input,select,textarea'); for (const input of inputs) { if (!input.disabled && !input.reportValidity()) return false; } return true; },
            goTo(step) { if (!this.busy && step >= 1 && step <= this.furthest) this.step = step; },
            async next() { if (this.busy || !this.validateStep()) return; if (this.step >= 4 && !(await this.calculate())) return; if (this.step < 6) { this.step++; this.furthest = Math.max(this.furthest, this.step); } },
            payload() { return {...this.form, recipes: this.form.recipes.map(({raw_material_id, amount, unit, notes}) => ({raw_material_id, amount, unit, notes})), target_margin: this.form.target_margin === '' ? null : this.form.target_margin, target_markup: this.form.target_markup === '' ? null : this.form.target_markup}; },
            async request(url, method, payload) {
                const response = await fetch(url, {method, headers: {'Content-Type': 'application/json', 'Accept': 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content}, body: JSON.stringify(payload)});
                const data = await response.json();
                if (!response.ok) throw new Error(data.errors ? Object.values(data.errors).flat().join(' ') : data.message || 'Permintaan gagal. Silakan coba lagi.');
                return data;
            },
            showError(error) { this.error = error.message; this.$nextTick(() => this.$refs.errorBox.focus()); },
            async send(url, method) {
                if (this.busy) return false;
                this.busy = true; this.error = ''; this.saved = '';
                try { const data = await this.request(url, method, this.payload()); this.result = data.result; this.saved = data.message || ''; return true; }
                catch (error) { this.result = null; this.showError(error); return false; }
                finally { this.busy = false; }
            },
            calculate() { return this.send({{ Illuminate\Support\Js::from(route('admin.hpp.calculate')) }}, 'POST'); },
            save() { return this.send({{ Illuminate\Support\Js::from($product ? route('admin.hpp.update', $product->id) : null) }}, 'PUT'); },
            async createMaterial() {
                if (this.busy) return;
                this.busy = true; this.error = '';
                try {
                    const data = await this.request({{ Illuminate\Support\Js::from(route('admin.hpp.materials.store')) }}, 'POST', this.newMaterial);
                    this.materials.push(data.material);
                    let row = this.form.recipes.find(row => !row.raw_material_id);
                    if (!row) { if (this.form.recipes.length >= 100) { this.saved = 'Bahan tersimpan. Hapus satu baris sebelum memilihnya.'; return; } this.addRow(); row = this.form.recipes[this.form.recipes.length - 1]; }
                    row.raw_material_id = data.material.id; row.unit = ''; this.materialSearch = ''; this.invalidate(); this.saved = 'Bahan tersimpan dengan stok awal nol dan dipilih pada resep.';
                    this.newMaterial = {name: '', purchase_total: '', purchase_quantity: '', unit: 'ml'};
                } catch (error) { this.showError(error); }
                finally { this.busy = false; }
            },
        };
    }
    </script>
</div></div>
</body>
</html>
